-- 注意: JSON 列使用 JSONB；标识符统一双引号小写。
CREATE TABLE IF NOT EXISTS "sys_demo" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" VARCHAR(32) NOT NULL,
    "desc_text" TEXT,
    "qty" INTEGER DEFAULT 0 NOT NULL,
    "amount" NUMERIC(18,4),
    "enabled" BOOLEAN DEFAULT TRUE NOT NULL,
    "biz_date" DATE,
    "created_time" TIMESTAMP,
    "status" VARCHAR(16) DEFAULT 'NEW' NOT NULL,
    "extra" JSONB,
    "trace_id" UUID,
    "created_dept" VARCHAR(128),
    "created_at" TIMESTAMP NOT NULL,
    "created_by" VARCHAR(64),
    "updated_at" TIMESTAMP NOT NULL,
    "updated_by" VARCHAR(64),
    CONSTRAINT "pk_sys_demo" PRIMARY KEY ("id"),
    CONSTRAINT "uk_sys_demo_code" UNIQUE ("code")
);

COMMENT ON TABLE "sys_demo" IS '演示表（覆盖全部列类型与明细表）';
